frappe.ui.form.on('Review', {
    visited_date: function(frm, cdt, cdn) {
        calculate_next_visit(frm, cdt, cdn);
    },
    days: function(frm, cdt, cdn) {
        setTimeout(function() {
            calculate_next_visit(frm, cdt, cdn);
        }, 500);
    }
});

function calculate_next_visit(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    var visited_date = row.visited_date;
    var days = parseInt(row.days);

    if (!visited_date || !days || isNaN(days)) return;

    var parts      = visited_date.split('-');
    var year       = parseInt(parts[0]);
    var month      = parseInt(parts[1]) - 1;
    var day        = parseInt(parts[2]);
    var date_obj   = new Date(year, month, day);
    date_obj.setDate(date_obj.getDate() + days);

    var next_year  = date_obj.getFullYear();
    var next_month = String(date_obj.getMonth() + 1).padStart(2, '0');
    var next_day   = String(date_obj.getDate()).padStart(2, '0');
    var next_date  = next_year + '-' + next_month + '-' + next_day;

    frappe.model.set_value(cdt, cdn, 'next_visit_date', next_date);
    frm.refresh_field('Review');
}

