frappe.ui.form.on("Patient Appointment", {
 
    // Triggered when "Check Availability" button is clicked
    // and the slot dialog opens — we hook into it here
    refresh: function(frm) {
 
        // Inject CSS once for blurred/booked slots
        if (!document.getElementById("booked-slot-style")) {
            let style = document.createElement("style");
            style.id = "booked-slot-style";
            style.innerHTML = `
                /* Already booked slot */
                .booked-slot {
                    filter: blur(2px) !important;
                    opacity: 0.35 !important;
                    pointer-events: none !important;
                    cursor: not-allowed !important;
                    background-color: #ffe5e5 !important;
                    border-color: #ff9999 !important;
                    color: #cc0000 !important;
                    position: relative;
                }
 
                /* Past time slot */
                .past-slot {
                    filter: blur(2px) !important;
                    opacity: 0.35 !important;
                    pointer-events: none !important;
                    cursor: not-allowed !important;
                    background-color: #f0f0f0 !important;
                    border-color: #cccccc !important;
                    color: #999999 !important;
                }
            `;
            document.head.appendChild(style);
        }
 
        // Override the slot rendering after dialog opens
        // We observe DOM changes to catch when slots are rendered
        let observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                mutation.addedNodes.forEach(function(node) {
                    if (node.nodeType === 1) {
                        // Look for the slot dialog content
                        let slotContainer = node.querySelector
                            ? node.querySelector(".slot-info")
                            : null;
 
                        if (!slotContainer) {
                            slotContainer = node.classList &&
                                node.classList.contains("slot-info")
                                ? node : null;
                        }
 
                        if (slotContainer) {
                            apply_blur_on_booked_slots(frm, slotContainer);
                        }
                    }
                });
            });
        });
 
        observer.observe(document.body, { childList: true, subtree: true });
    }
});
 
 
// ============================================================
// CORE FUNCTION: Fetches booked appointments and blurs slots
// ============================================================
function apply_blur_on_booked_slots(frm, container) {
 
    let practitioner = frm.doc.practitioner;
    let date         = frm.doc.appointment_date;
 
    if (!practitioner || !date) return;
 
    // Fetch already booked appointments for this practitioner + date
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype : "Patient Appointment",
            filters : {
                practitioner      : practitioner,
                appointment_date  : date,
                status            : ["not in", ["Cancelled"]]
            },
            fields  : ["appointment_time", "patient_name"],
            limit_page_length: 500
        },
        callback: function(r) {
            if (!r || !r.message) return;
 
            // Build a Set of booked "HH:MM" times
            let booked_times = new Set(
                r.message.map(function(appt) {
                    // appointment_time comes as "HH:MM:SS" — take first 5 chars
                    return String(appt.appointment_time).substring(0, 5);
                })
            );
 
            // Get current time for "past slot" check (only if today)
            let today    = frappe.datetime.get_today();  // "YYYY-MM-DD"
            let now_time = frappe.datetime.now_time().substring(0, 5); // "HH:MM"
            let is_today = (date === today);
 
            // Find all rendered slot buttons inside the dialog
            // Frappe Health renders them as <span class="btn btn-default" data-name="HH:MM:SS">
            let slot_buttons = document.querySelectorAll(
                ".modal .slot-info .btn, " +           // standard modal
                ".modal-body .btn[data-name], " +      // fallback
                "[data-name].btn"                      // generic fallback
            );
 
            slot_buttons.forEach(function(btn) {
                let slot_time = String(btn.getAttribute("data-name") || "")
                                    .substring(0, 5);  // "HH:MM"
 
                if (!slot_time) return;
 
                // ---- 1. Check if BOOKED ----
                if (booked_times.has(slot_time)) {
                    btn.classList.add("booked-slot");
                    btn.setAttribute("title", "Already Booked");
                    btn.setAttribute("disabled", "disabled");
                    return;
                }
 
                // ---- 2. Check if PAST (only if today's date) ----
                if (is_today && slot_time <= now_time) {
                    btn.classList.add("past-slot");
                    btn.setAttribute("title", "Time Already Passed");
                    btn.setAttribute("disabled", "disabled");
                }
            });
        }
    });
}

