function calculate_all(frm) {

    let total_discount = 0;
    let total_cgst_amount = 0;
    let total_sgst_amount = 0;

    (frm.doc.items || []).forEach(function(item) {

        let amount = flt(item.amount);

        let discount_amount =
            amount * flt(item.discount_percentage || 0) / 100;

        let taxable_amount =
            amount - discount_amount;

        let cgst_amount =
            taxable_amount * flt(item.custom_cgst_ || 0) / 100;

        let sgst_amount =
            taxable_amount * flt(item.custom_sgst_ || 0) / 100;

        total_discount += discount_amount;
        total_cgst_amount += cgst_amount;
        total_sgst_amount += sgst_amount;
    });

    let total_gst_amount =
        total_cgst_amount + total_sgst_amount;

    frm.set_value(
        "custom_overall_discount",
        total_discount
    );

    frm.set_value(
        "custom_cgst",
        total_cgst_amount
    );

    frm.set_value(
        "custom_sgst",
        total_sgst_amount
    );

    frm.set_value(
        "custom_total_gst",
        total_gst_amount
    );

    calculate_balance(frm);
}

function calculate_balance(frm) {

    let cash_received =
        flt(frm.doc.custom_cash_received || 0);

    let bill_amount =
        flt(frm.doc.rounded_total || frm.doc.grand_total || 0);

    let balance =
        cash_received - bill_amount;

    if (balance < 0) {
        balance = 0;
    }

    frm.set_value(
        "custom_balance_",
        balance
    );
}

