function calculate_row(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    // Amount = Qty * Rate
    row.custom_total_amount = flt(row.qty) * flt(row.custom_rate);

    // Discount amount (currency, based on Dis %)
    let discount_amt = flt(row.custom_total_amount) * flt(row.custom_dis_) / 100;
    let after_discount = flt(row.custom_total_amount) - discount_amt;

    // GST amount (applied on discounted value)
    let gst_amt = after_discount * flt(row.custom_gst) / 100;

    // Net Amount
    row.custom_net_amount_ = after_discount + gst_amt;

    frm.refresh_field("items");
    calculate_totals(frm);
}

function calculate_totals(frm) {
    let total = 0;
    let total_discount = 0;
    let total_gst = 0;
    let net_total = 0;

    (frm.doc.items || []).forEach(function(row) {
        total += flt(row.custom_total_amount);

        let discount_amt = flt(row.custom_total_amount) * flt(row.custom_dis_) / 100;
        total_discount += discount_amt;

        let after_discount = flt(row.custom_total_amount) - discount_amt;
        total_gst += after_discount * flt(row.custom_gst) / 100;

        net_total += flt(row.custom_net_amount_);
    });

    frm.set_value("custom_total_", total);
    frm.set_value("custom_discount_", total_discount);
    frm.set_value("custom_gst", total_gst);
    frm.set_value("custom_total_net_amount_", net_total);

    let rounded = Math.round(net_total);
    frm.set_value("custom_rounding_off", rounded - net_total);
}

