frappe.ui.form.on("Sales Invoice Item", {

    item_code(frm, cdt, cdn) {

        if (frm.doc.docstatus !== 0) return;

        let row = locals[cdt][cdn];

        if (!row.item_code) return;

        frappe.db.get_value("Item", row.item_code, [
            "custom_cgst_",
            "custom_sgst_",
            "custom_discount"
        ]).then(r => {

            if (!r.message) return;

            frappe.model.set_value(cdt, cdn, "custom_cgst_", flt(r.message.custom_cgst_));
            frappe.model.set_value(cdt, cdn, "custom_sgst_", flt(r.message.custom_sgst_));
            frappe.model.set_value(cdt, cdn, "discount_percentage", flt(r.message.custom_discount));

            setTimeout(() => {
                calculate_all(frm);
            }, 200);
        });
    },

    qty(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    },

    rate(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    },

    amount(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    },

    discount_percentage(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    },

    custom_cgst_(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    },

    custom_sgst_(frm) {
        if (frm.doc.docstatus === 0) calculate_all(frm);
    }
});


function calculate_all(frm) {

    if (frm.doc.docstatus !== 0) return;

    let total_discount = 0;
    let total_cgst = 0;
    let total_sgst = 0;

    (frm.doc.items || []).forEach(function(item) {

        let gross = flt(item.amount);

        let discount = gross * flt(item.discount_percentage || 0) / 100;

        let taxable = gross - discount;

        let cgst = taxable * flt(item.custom_cgst_ || 0) / 100;

        let sgst = taxable * flt(item.custom_sgst_ || 0) / 100;

        total_discount += discount;
        total_cgst += cgst;
        total_sgst += sgst;
    });

    frm.set_value("custom_overall_discount", frappe.utils.rounded(total_discount, 2));
    frm.set_value("custom_cgst", frappe.utils.rounded(total_cgst, 2));
    frm.set_value("custom_sgst", frappe.utils.rounded(total_sgst, 2));
    frm.set_value("custom_total_gst", frappe.utils.rounded(total_cgst + total_sgst, 2));

    calculate_balance(frm);
}


function calculate_balance(frm) {

    if (frm.doc.docstatus !== 0) return;

    let cash = flt(frm.doc.custom_cash_received || 0);

    let bill = flt(frm.doc.rounded_total || frm.doc.grand_total || 0);

    let balance = cash - bill;

    if (balance < 0) balance = 0;

    frm.set_value("custom_balance_", balance);
}

