frappe.ui.form.on('Sales Invoice Item', {
    item_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.item_code) {
            frappe.model.set_value(cdt, cdn, "custom_stock", null);
            return;
        }

        // Item groups that represent physical stock items
        const stock_item_groups = [
            "Tablets", "Bandages", "IV Set", "Injections",
            "Ointment", "Plaster", "Drug", "Syringe", "Syrups"
        ];

        frappe.db.get_value("Item", row.item_code, "item_group", (item_r) => {
            let item_group = item_r && item_r.item_group;

            // Not a stock category (Services, Procedure, Radiology, Laboratory, etc.)
            if (!stock_item_groups.includes(item_group)) {
                frappe.model.set_value(cdt, cdn, "custom_stock", null);
                return;
            }

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Bin",
                    filters: {
                        item_code: row.item_code,
                        warehouse: "Stores - SH"
                    },
                    fields: ["actual_qty"]
                },
                callback: function(r) {
                    let qty = (r.message && r.message.length) ? r.message[0].actual_qty : 0;
                    frappe.model.set_value(cdt, cdn, "custom_stock", qty);
                    frm.fields_dict["items"].grid.refresh();
                }
            });
        });
    }
});

