frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        set_stock_formatter(frm);
    },
    onload: function(frm) {
        set_stock_formatter(frm);
    }
});

function set_stock_formatter(frm) {
    let grid_field = frm.fields_dict["items"].grid.get_field("custom_stock");
    if (!grid_field) return;

    grid_field.df.read_only = 1;
    grid_field.df.formatter = function(value, df, options, doc) {
        // Blank for billing-only items (Services, Procedure, Radiology, Lab, etc.)
        if (value === null || value === undefined || value === "") {
            return "";
        }
        let color;
        if (value <= 5) {
            color = "red";
        } else if (value <= 20) {
            color = "orange";
        } else {
            color = "green";
        }
        return `<span style="color:${color}; font-weight:bold;">${value}</span>`;
    };
    frm.fields_dict["items"].grid.refresh();
}

frappe.ui.form.on("Sales Invoice Item", {
    item_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        frappe.db.get_value("Item", row.item_code, [
            "custom_cgst_",
