frappe.ui.form.on("Sales Invoice Item", {
    qty(frm) {
        calculate_all(frm);
    },
    rate(frm) {
        calculate_all(frm);
    },
    custom_dis_amt_qty(frm) {
        calculate_all(frm);
    },
    custom_cgst_(frm) {
        calculate_all(frm);
    },
    custom_sgst_(frm) {
        calculate_all(frm);
    }
});
 
function calculate_all(frm) {
    let total_amount = 0;      // Gross total (before discount) -> "Total Amount" in image
    let total_discount = 0;    // Sum of (Dis.Amt/Qty * Qty)
    let total_cgst = 0;
    let total_sgst = 0;
 
    (frm.doc.items || []).forEach(function (item) {
        let qty = flt(item.qty);
        let rate = flt(item.rate);                     // Rate/Qty (already net, after discount)
        let dis_amt_qty = flt(item.custom_dis_amt_qty); // Dis.Amt/Qty (rupees per unit)
 
        // Net Amount = Rate/Qty * Qty  (this is the "Amount" column in the item table)
        let amount = qty * rate;
        frappe.model.set_value(item.doctype, item.name, "amount", amount);
 
        // Line discount = Dis.Amt/Qty * Qty
        let discount_amount = dis_amt_qty * qty;
 
        // Gross line amount (before discount) = Amount + Discount
        let gross_amount = amount + discount_amount;
 
        // GST calculated on the NET amount (rate * qty), not re-discounted
        let cgst_amount = amount * flt(item.custom_cgst_ || 0) / 100;
        let sgst_amount = amount * flt(item.custom_sgst_ || 0) / 100;
 
        total_amount += gross_amount;
        total_discount += discount_amount;
        total_cgst += cgst_amount;
        total_sgst += sgst_amount;
    });
 
    let total_gst = total_cgst + total_sgst;
 
    // Net amount before rounding
    let net_before_round = total_amount - total_discount;
 
    // Auto round to nearest rupee
    let rounded_net = Math.round(net_before_round);
    let rounding_off = flt(rounded_net - net_before_round, 2);
 
    // ---- Footer fields ----
    frm.set_value("custom_total_amount", flt(total_amount, 2));
    frm.set_value("custom_overall_discount", flt(total_discount, 2));
    frm.set_value("custom_cgst", flt(total_cgst, 2));
    frm.set_value("custom_sgst", flt(total_sgst, 2));
    frm.set_value("custom_total_gst", flt(total_gst, 2));   // informational only, not added to net
    frm.set_value("custom_rounding_off", rounding_off);
    frm.set_value("custom_net_amount", rounded_net);
 
    calculate_balance(frm);
}
 
function calculate_balance(frm) {
    let cash_received = flt(frm.doc.custom_cash_received || 0);
    let net_amount = flt(frm.doc.custom_net_amount || 0);
 
    // Balance can be negative (amount due) or positive (change/overpaid)
    let balance = flt(cash_received - net_amount, 2);
 
    frm.set_value("custom_balance_", balance);
}

