function setup_patient_encounter_highlight() {
    if (window.__pe_highlight_setup) return;
    window.__pe_highlight_setup = true;

    const observer = new MutationObserver((mutations) => {
        mutations.forEach((m) => {
            m.addedNodes.forEach((node) => {
                if (node.nodeType !== 1) return;

                let $ul = $(node).is("ul.awesomplete") ? $(node) : $(node).find("ul.awesomplete");
                if (!$ul.length) return;

                let $wrapper = $ul.closest(".awesomplete");
                let $control = $wrapper.closest(".frappe-control");
                let fieldname = $control.attr("data-fieldname");

                // must be the encounter field AND inside a dialog/modal
                let insideModal = $control.closest(".modal").length > 0;

                if (fieldname !== "encounter" || !insideModal) return;

                setTimeout(() => highlight_and_sort($ul), 30);
            });
        });
    });

    observer.observe(document.body, { childList: true, subtree: true });
}

function highlight_and_sort($ul) {
    let today = frappe.datetime.get_today(); // "2026-07-06"
    let $items = $ul.find("li").get();

    $items.forEach((li) => {
        let $li = $(li);
        let text = $li.text();
        let match = text.match(/(\d{4}-\d{2}-\d{2})/);
        let date = match ? match[1] : "";
        $li.attr("data-enc-date", date);

        if (date === today) {
            $li.css({
                "background-color": "#d3f9d8",
                "border-left": "4px solid #2f9e44"
            });
        } else if (date) {
            $li.css({
                "background-color": "#ffe3c9",
                "border-left": "4px solid #e8590c"
            });
        }
    });

    $items.sort((a, b) => {
        let da = $(a).attr("data-enc-date") || "";
        let db = $(b).attr("data-enc-date") || "";
        return db.localeCompare(da);
    });

    $ul.empty();
    $items.forEach((li) => $ul.append(li));
}

