frappe.ui.form.on("Purchase Invoice", {
    refresh(frm) {
        calculate_purchase_totals(frm);
    },

    validate(frm) {
        calculate_purchase_totals(frm);
    }
});


frappe.ui.form.on("Purchase Invoice Item", {

    qty(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    custom_buy_rate(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    custom_buy_discount_(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    custom_gst(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    items_remove(frm) {
        calculate_purchase_totals(frm);
    }

});


function calculate_row(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    let qty = flt(row.qty);
    let rate = flt(row.custom_buy_rate);
    let discount = flt(row.custom_buy_discount_);
    let gst = flt(row.custom_gst);

    let buy_amount = qty * rate;

    let discount_amount = buy_amount * discount / 100;

    let taxable_amount = buy_amount - discount_amount;

    let gst_amount = taxable_amount * gst / 100;

    let buy_net_amount = taxable_amount + gst_amount;

    frappe.model.set_value(cdt, cdn, "custom_buy_amount", buy_amount);
    frappe.model.set_value(cdt, cdn, "custom_buy_net_amount_", buy_net_amount);

    setTimeout(() => {
        calculate_purchase_totals(frm);
    }, 50);
}



function calculate_purchase_totals(frm) {

    let total_qty = 0;
    let buy_total = 0;
    let total_discount = 0;
    let total_gst = 0;
    let buy_net_total = 0;

    (frm.doc.items || []).forEach(function(row) {

        let qty = flt(row.qty);
        let rate = flt(row.custom_buy_rate);
        let discount = flt(row.custom_buy_discount_);
        let gst = flt(row.custom_gst);

        let buy_amount = qty * rate;

        let discount_amount = buy_amount * discount / 100;

        let taxable_amount = buy_amount - discount_amount;

        let gst_amount = taxable_amount * gst / 100;

        let buy_net_amount = taxable_amount + gst_amount;

        row.custom_buy_amount = buy_amount;
        row.custom_buy_net_amount_ = buy_net_amount;

        total_qty += qty;
        buy_total += buy_amount;
        total_discount += discount_amount;
        total_gst += gst_amount;
        buy_net_total += buy_net_amount;
    });

    frm.refresh_field("items");

    frm.set_value("total_qty", total_qty);

    // Custom Totals Only
    frm.set_value("custom_buy_total", buy_total);
    frm.set_value("custom_total_discount", total_discount);
    frm.set_value("custom_total_gst", total_gst);
    frm.set_value("custom_buy_net_total_", buy_net_total);
}

frappe.ui.form.on("Payment Entry", {
    refresh(frm) {
        update_paid_amount(frm);
    },

    onload(frm) {
        update_paid_amount(frm);
    }
});

function update_paid_amount(frm) {

    if (!frm.doc.references || !frm.doc.references.length) return;

    let ref = frm.doc.references[0];

    if (ref.reference_doctype === "Purchase Invoice") {

        frappe.db.get_value(
            "Purchase Invoice",
            ref.reference_name,
            "custom_buy_net_total_"
        ).then(r => {

            if (r.message && r.message.custom_buy_net_total_) {

                frm.set_value("paid_amount", r.message.custom_buy_net_total_);

                frm.refresh_field("paid_amount");
            }

        });

    }
}

frappe.listview_settings["Patient"] = {
    formatters: {
        mobile(value) {
            if (!value) {
                return "";
            }

            const phone = String(value).replace(/\s+/g, "");

            // Don't mask very short numbers
            if (phone.length <= 4) {
                return phone;
            }

            const firstTwo = phone.slice(0, 2);
            const lastTwo = phone.slice(-2);
            const maskedCount = Math.max(phone.length - 4, 1);

            return `${firstTwo}${"*".repeat(maskedCount)}${lastTwo}`;
        }
    }
};

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        add_invoice_download_button(frm);
        hide_standard_download_button(frm);
    }
});

function add_invoice_download_button(frm) {
    if (!frm.fields_dict.items) {
        return;
    }

    const wrapper = frm.fields_dict.items.grid.wrapper;

    wrapper.find(".invoice-download-btn").remove();

    const button = $(
        '<button type="button" class="btn btn-xs btn-default invoice-download-btn" style="margin-left: 8px;">Download Invoice</button>'
    );

    const upload_button = wrapper.find(".grid-upload");

    if (upload_button.length) {
        button.insertAfter(upload_button);
    } else {
        button.appendTo(wrapper.find(".grid-footer"));
    }

    button.on("click", function () {
        download_invoice_csv(frm);
    });
}

function hide_standard_download_button(frm) {
    if (!frm.fields_dict.items) {
        return;
    }

    const wrapper = frm.fields_dict.items.grid.wrapper;

    wrapper
        .find("button, a")
        .filter(function () {
            return $(this).text().trim() === "Download";
        })
        .hide();
}

function download_invoice_csv(frm) {
    const items = frm.doc.items || [];

    if (!items.length) {
        frappe.msgprint({
            title: __("No Items"),
            message: __("There are no items available to download."),
            indicator: "orange"
        });
        return;
    }

    const headers = [
        "Item Name",
        "Quantity",
        "Rate",
        "CGST Amount",
        "SGST Amount",
        "Total GST",
        "Amount"
    ];

    const rows = items.map(item => [
        item.item_name || item.item_code || "",
        flt(item.qty),
        flt(item.rate, 2).toFixed(2),
        flt(item.custom_cgst_amount, 2).toFixed(2),
        flt(item.custom_sgst_amount, 2).toFixed(2),
        flt(item.custom_total_gst, 2).toFixed(2),
        flt(item.amount, 2).toFixed(2)
    ]);

    const csv = [
        headers,
        ...rows
    ]
        .map(row =>
            row.map(value => {
                value = String(value ?? "");

                if (
                    value.includes(",") ||
                    value.includes('"') ||
                    value.includes("\n")
                ) {
                    value = '"' + value.replace(/"/g, '""') + '"';
                }

                return value;
            }).join(",")
        )
        .join("\r\n");

    const blob = new Blob(
        ["\uFEFF" + csv],
        {
            type: "text/csv;charset=utf-8;"
        }
    );

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = "items-invoice.csv";

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    setTimeout(() => {
        URL.revokeObjectURL(url);
    }, 100);
}

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        add_invoice_download_button(frm);
        hide_standard_download_button(frm);
    },

    validate(frm) {
        calculate_custom_gst(frm);
    },

    before_submit(frm) {
        calculate_custom_gst(frm);
    }
});

function calculate_custom_gst(frm) {
    let total_cgst = 0;
    let total_sgst = 0;

    const parent_rates = get_parent_tax_rates(frm);

    (frm.doc.items || []).forEach(item => {
        let cgst_rate = parent_rates.cgst;
        let sgst_rate = parent_rates.sgst;

        const item_rates = get_item_tax_rates(item);

        if (item_rates.has_rates) {
            cgst_rate = item_rates.cgst;
            sgst_rate = item_rates.sgst;
        }

        const amount = flt(item.amount);

        const cgst = flt(amount * cgst_rate / 100, 2);
        const sgst = flt(amount * sgst_rate / 100, 2);
        const total_gst = flt(cgst + sgst, 2);

        item.custom_cgst_amount = cgst;
        item.custom_sgst_amount = sgst;
        item.custom_total_gst = total_gst;

        total_cgst += cgst;
        total_sgst += sgst;
    });

    total_cgst = flt(total_cgst, 2);
    total_sgst = flt(total_sgst, 2);

    const total_gst = flt(total_cgst + total_sgst, 2);

    frm.doc.custom_cgst = total_cgst;
    frm.doc.custom_sgst = total_sgst;
    frm.doc.custom_total_gst = total_gst;

    frm.refresh_field("items");
    frm.refresh_field("custom_cgst");
    frm.refresh_field("custom_sgst");
    frm.refresh_field("custom_total_gst");
}

function get_parent_tax_rates(frm) {
    let cgst = 0;
    let sgst = 0;

    (frm.doc.taxes || []).forEach(tax => {
        const account = String(tax.account_head || "").toUpperCase();

        if (account.includes("CGST")) {
            cgst = flt(tax.rate);
        }

        if (account.includes("SGST")) {
            sgst = flt(tax.rate);
        }
    });

    return {
        cgst,
        sgst
    };
}

function get_item_tax_rates(item) {
    let cgst = 0;
    let sgst = 0;
    let has_rates = false;

    if (!item.item_tax_rate) {
        return {
            cgst,
            sgst,
            has_rates
        };
    }

    let tax_rates = {};

    try {
        tax_rates =
            typeof item.item_tax_rate === "string"
                ? JSON.parse(item.item_tax_rate)
                : item.item_tax_rate;
    } catch (error) {
        return {
            cgst,
            sgst,
            has_rates
        };
    }

    Object.entries(tax_rates || {}).forEach(([account, rate]) => {
        const account_name = String(account || "").toUpperCase();
        const tax_rate = flt(rate);

        if (account_name.includes("CGST")) {
            cgst = tax_rate;
            has_rates = true;
        }

        if (account_name.includes("SGST")) {
            sgst = tax_rate;
            has_rates = true;
        }
    });

    return {
        cgst,
        sgst,
        has_rates
    };
}

